-- 814 dòng media (ảnh/bản vẽ/panorama) cho toàn bộ 6 làng — ảnh vật lý phục vụ
-- tĩnh từ map-tour/public/<slug-làng>/... (đã có sẵn trong repo, không cần
-- tải lại từ Google Drive/Excel). Các cột owner_entity_id trỏ tới các bảng đã
-- seed ở migration 002-010 phía trên.
-- Idempotent: UPSERT theo id cố định.
--
-- LƯU Ý về cột `kind`: ảnh 360 (equirectangular) LUÔN có tỉ lệ đúng 2:1
-- (5888x2944 hoặc 11904x5952 tuỳ máy). Giá trị `kind` dưới đây đã được đối
-- chiếu với kích thước pixel thực tế của từng file, KHÔNG theo caption — vì
-- caption "Ảnh 360" trong Excel thường là ô gộp cho cả một nhóm ảnh, khiến
-- script import gắn nhầm cho ảnh thường. Khi thêm media mới, giữ nguyên quy
-- tắc này, nếu không nút "Xem 360°" sẽ mở ảnh phẳng trong viewer 360.

ON CONFLICT (id) DO UPDATE SET
  "url" = EXCLUDED."url",
  "kind" = EXCLUDED."kind",
  "attribution" = EXCLUDED."attribution",
  "caption" = EXCLUDED."caption",
  "owner_entity_type" = EXCLUDED."owner_entity_type",
  "owner_entity_id" = EXCLUDED."owner_entity_id",
  "created_at" = EXCLUDED."created_at",
  "updated_at" = EXCLUDED."updated_at";
